// programs lists the sources of examples/, of cakec's tests and of the
// uncaught goldens, from the Go test that holds this file to having them all.
function programs() {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'strip-programs-'));
  const out = path.join(tmp, 'programs.json');
  try {
    execFileSync('go', ['test', './lower', '-count=1', '-run', '^TestStripGoldensHoldTheTestPrograms$',
      '-args', `-strip-programs-out=${out}`], { cwd: ROOT, stdio: 'inherit' });
    return JSON.parse(fs.readFileSync(out, 'utf8'));
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}

function record(section, name, src) {
  try {
    return { section, name, src, lines: stripTypeScriptTypes(src).split(LINES) };
  } catch (e) {
    if (!e.code?.startsWith('ERR_')) throw e;
    return { section, name, src, refused: `${e.code}: ${e.message.split('\n')[0]}` };
  }
}

const cases = [];
for (const [section, srcs] of Object.entries(SECTIONS)) {
  srcs.forEach((src, i) => cases.push(record(section, `${section} ${i + 1}`, src)));
}
for (const p of programs()) {
  const section = p.name.startsWith('examples/') ? 'EXAMPLES' : p.name.startsWith('backend/') ? 'UNCAUGHT' : 'CAKEC_TESTS';
  cases.push(record(section, p.name, p.src));
}

// U+2028 and U+2029 are written escaped, so a line of the file is a case.
const SEPARATORS = new RegExp('[' + LS + PS + ']', 'g');
const escape = (ch) => String.fromCharCode(92) + 'u' + ch.charCodeAt(0).toString(16);
fs.writeFileSync(OUT, cases.map((x) => JSON.stringify(x).replace(SEPARATORS, escape)).join('\n') + '\n');
const counts = {};
for (const x of cases) counts[x.section] = (counts[x.section] ?? 0) + 1;
console.log(`wrote ${cases.length} cases to ${path.relative(ROOT, OUT)}:`, counts);
